const ahora = new Date();

const etapasValidas = [
  'nuevo',
  'calificando',
  'clasificado',
  'precio_dado'
];

const elegibles = [];

for (const item of $input.all()) {
  const lead = item.json;

  // Validar etapa
  if (!etapasValidas.includes(lead.Etapa)) continue;

  // Validar que no se haya enviado follow-up ya
  const followups = parseInt(lead['Followups Enviados'] || '0');
  if (followups > 0) continue;

  // Excluir leads escalados (ya los maneja el equipo manualmente)
  const etiquetas = (lead.Etiquetas || '').toLowerCase();
  if (etiquetas.includes('escalado')) continue;

  // Validar que tenga Conversation ID
  const convId = String(lead['Conversation ID'] || '').trim();
  if (!convId || convId === 'undefined') continue;

  // Validar que tenga WhatsApp real (no null)
  const whatsapp = String(lead.WhatsApp || '').trim();
  if (!whatsapp || whatsapp === 'null' || whatsapp === 'undefined') continue;

  // Validar que tenga Ultima Interaccion
  const ultimaStr = lead['Ultima Interaccion'];
  if (!ultimaStr) continue;

  // Calcular horas desde ultima interaccion
  const ultimaInteraccion = new Date(ultimaStr);
  const horasTranscurridas = (ahora - ultimaInteraccion) / (1000 * 60 * 60);

  // Entre 6 y 24 horas (dentro de la ventana de Meta)
  if (horasTranscurridas >= 6 && horasTranscurridas < 24) {
    const etapa = lead.Etapa;
    const servicio = (lead.Servicio || '').toLowerCase();
    const nombre = lead.Nombre || '';

    // Saludo personalizado
    const saludo = nombre ? `Hola ${nombre}!` : 'Hola!';

    let mensaje = '';

    if (etapa === 'nuevo') {
      if (servicio.includes('chatbot')) {
        mensaje = `${saludo} Vi que nos escribiste sobre chatbots para tu negocio. Si tienes alguna duda o quieres platicar cómo funciona, aquí estamos 😊`;
      } else if (servicio.includes('automatizacion')) {
        mensaje = `${saludo} Vi que nos escribiste sobre automatización. Si quieres platicar qué proceso te gustaría automatizar, con gusto te ayudo 😊`;
      } else if (servicio.includes('web_seo')) {
        mensaje = `${saludo} Vi que nos escribiste sobre Activos Digitales para aparecer en Google. Si tienes alguna duda o quieres que te platique cómo funciona, aquí estamos 😊`;
      } else if (servicio.includes('web_sin_seo')) {
        mensaje = `${saludo} Vi que nos escribiste sobre diseño web. Si tienes alguna duda o quieres ver ejemplos de nuestro trabajo, con gusto te ayudo 😊`;
      } else {
        mensaje = `${saludo} Vi que nos escribiste y nos quedamos pendientes. Si tienes alguna duda sobre nuestros servicios, aquí estamos para ayudarte 😊`;
      }
    } else if (etapa === 'calificando') {
      if (servicio.includes('chatbot')) {
        mensaje = `${saludo} Nos quedamos platicando sobre el chatbot para tu negocio. Tienes alguna duda? Con gusto te ayudo 😊`;
      } else if (servicio.includes('automatizacion')) {
        mensaje = `${saludo} Nos quedamos platicando sobre la automatización. Quieres que retomemos? 😊`;
      } else if (servicio.includes('web_seo')) {
        mensaje = `${saludo} Nos quedamos platicando sobre tu Activo Digital. Si quieres que te platique más o agendar una llamada rápida, aquí estoy 😊`;
      } else if (servicio.includes('web_sin_seo')) {
        mensaje = `${saludo} Nos quedamos platicando sobre tu página web. Tienes alguna duda? 😊`;
      } else {
        mensaje = `${saludo} Nos quedamos platicando y quería ver si tienes alguna duda. Aquí estamos 😊`;
      }
    } else if (etapa === 'clasificado' || etapa === 'precio_dado') {
      if (servicio.includes('chatbot')) {
        mensaje = `${saludo} Te quería recordar la info que te compartí sobre los chatbots. Si tienes alguna duda o quieres agendar una demo, con gusto 📅`;
      } else if (servicio.includes('automatizacion')) {
        mensaje = `${saludo} Te quería recordar lo que platicamos sobre automatización. Quieres agendar una videollamada para ver los detalles? 📅`;
      } else if (servicio.includes('web_seo')) {
        mensaje = `${saludo} Te quería recordar la info de los Activos Digitales que te compartí. Si quieres platicar más a detalle o agendar una llamada, aquí estoy 📅`;
      } else if (servicio.includes('web_sin_seo')) {
        mensaje = `${saludo} Te quería recordar la info que te compartí sobre tu página web. Si quieres avanzar o tienes alguna duda, aquí estamos 😊`;
      } else {
        mensaje = `${saludo} Te quería recordar la info que te compartimos. Si tienes alguna duda o quieres agendar una llamada, con gusto te ayudo 📅`;
      }
    }

    elegibles.push({
      json: {
        mensaje: mensaje,
        conversation_id: convId,
        whatsapp: whatsapp,
        followups_nuevo: String(followups + 1),
        nombre: nombre,
        negocio: lead.Negocio || '',
        etapa: etapa,
        servicio: servicio
      }
    });
  }
}

return elegibles;
